import os
import re
import csv
from datetime import date, timedelta

LOG_DIR = "/app/logs"
TODAY = date(2025, 8, 12)
LAST_7_START = TODAY - timedelta(days=6)
LAST_30_START = TODAY - timedelta(days=29)
MONTH_START = TODAY.replace(day=1)

FILENAME_RE = re.compile(r'^(\d{4}-\d{2}-\d{2})_.+\.log$')
SEVERITIES = ["ERROR", "WARNING", "INFO"]

periods = {
    "today": lambda d: d == TODAY,
    "last_7_days": lambda d: LAST_7_START <= d <= TODAY,
    "last_30_days": lambda d: LAST_30_START <= d <= TODAY,
    "month_to_date": lambda d: MONTH_START <= d <= TODAY,
    "total": lambda d: True,
}

counts = {p: {s: 0 for s in SEVERITIES} for p in periods}

for fname in os.listdir(LOG_DIR):
    m = FILENAME_RE.match(fname)
    if not m:
        continue
    file_date = date.fromisoformat(m.group(1))
    sev_counts = {s: 0 for s in SEVERITIES}
    path = os.path.join(LOG_DIR, fname)
    with open(path, "r", errors="replace") as f:
        for line in f:
            for sev in SEVERITIES:
                if f"[{sev}]" in line:
                    sev_counts[sev] += 1
                    break
    for pname, pred in periods.items():
        if pred(file_date):
            for sev in SEVERITIES:
                counts[pname][sev] += sev_counts[sev]

with open("/app/summary.csv", "w", newline="") as f:
    writer = csv.writer(f)
    writer.writerow(["period", "severity", "count"])
    for pname in ["today", "last_7_days", "last_30_days", "month_to_date", "total"]:
        for sev in SEVERITIES:
            writer.writerow([pname, sev, counts[pname][sev]])

print("done")

